import torch
from torch.utils.cpp_extension import load_inline
from task import input_t, output_t

# ---------------------------------------------------------------------------
# Small-shape host-launch reduction for batched square QR (geqrf).
#
# torch.geqrf dispatches a true *batched* cuBLAS geqrfBatched path (one launch
# for the whole batch, ~4 kernels total) only for small n; above an internal
# threshold (between n=176 and n=352 on this build) it falls back to a
# *per-matrix* cuSOLVER loop that issues ~80 kernel launches PER MATRIX. For the
# launch-overhead-bound benchmark shapes (n=352, batch=40: ~3200 host launches
# per call) that per-matrix loop is pure host-dispatch tax that dominates the
# tiny GPU compute. This shim exposes cuBLAS's batched geqrf directly so we can
# route the launch-bound shapes through the 4-launch path instead.
#
# The factors returned are the exact LAPACK compact-Householder (H, tau) that
# torch.geqrf produces, so the checker (Q = householder_product(H, tau),
# R = triu(H)) sees an identical factorization.
# ---------------------------------------------------------------------------

_CPP = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/cuda/CUDABlas.h>
#include <c10/cuda/CUDACachingAllocator.h>
#include <vector>

// Returns (H, tau) matching torch.geqrf for a [batch, n, n] float32 CUDA tensor,
// computed via cublas*geqrfBatched (single batched launch).
std::vector<at::Tensor> geqrf_batched(at::Tensor A) {
  TORCH_CHECK(A.dim() == 3, "expected [batch, n, n]");
  TORCH_CHECK(A.scalar_type() == at::kFloat, "float32 only");
  auto batch = A.size(0);
  auto n = A.size(1);
  TORCH_CHECK(A.size(2) == n, "square only");

  // cuBLAS geqrfBatched is column-major and in-place. Build a column-major
  // working copy (its .mT is contiguous), operate in place, then the logical
  // [batch,n,n] view is the LAPACK geqrf layout torch.geqrf returns.
  // cloneBatchedColumnMajor: transpose last two dims, make contiguous, transpose back.
  auto Hcol = A.mT().contiguous().mT();  // column-major storage, logical [b,n,n]
  auto tau = at::empty({batch, n}, A.options());

  auto handle = at::cuda::getCurrentCUDABlasHandle();

  // Arrays of device pointers (one per matrix) for A and tau.
  auto stride_A = Hcol.stride(0);
  auto stride_tau = tau.stride(0);
  float* A_base = Hcol.data_ptr<float>();
  float* tau_base = tau.data_ptr<float>();

  std::vector<float*> A_ptrs(batch), tau_ptrs(batch);
  for (int64_t i = 0; i < batch; ++i) {
    A_ptrs[i] = A_base + i * stride_A;
    tau_ptrs[i] = tau_base + i * stride_tau;
  }
  // Device pointer arrays.
  auto opts_ptr = at::TensorOptions().dtype(at::kLong).device(A.device());
  auto A_ptr_dev = at::from_blob(A_ptrs.data(), {batch},
                                 at::TensorOptions().dtype(at::kLong)).to(A.device());
  auto tau_ptr_dev = at::from_blob(tau_ptrs.data(), {batch},
